-- 2. their 17 details rows: proof hint, safety note, credit, quotation, source, licence
insert into public.action_mission_details
  (mission_id, catalog, slug, proof_hint, safety_note, credit_line, about, about_credit, source_url,
   license_name, license_url, doi)
select v.mission_id, 'drawdown', v.slug, v.proof_hint, v.safety_note, v.credit_line, v.about, v.about_credit,
       v.source_url, v.license_name, v.license_url, v.doi
  from (values
    ('f7eeae72-b28f-5183-a392-f527edaf73ec'::uuid, 'drawdown-use-low-flow-fixtures',
     'A photo of your timing notes and a link to any local water-saving offer.',
     'Use cold water to avoid scalds, mop up spills so no one slips, and don''t take fixtures apart.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/use-low-flow-fixtures), used with permission. Adapted: the mission wording is original.',
     'Low-flow fixtures reduce GHG emissions by reducing the volume of hot water used and therefore reducing the emissions from the energy used to heat that water (Kenway et al., 2023). Reduced water usage also leads to fewer emissions from treating and pumping water for domestic use (Yateh et al., 2024). Low-flow fixtures are low-cost and simple to install.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/use-low-flow-fixtures', null, null, null),
    ('9d1fdc5d-7617-5408-9269-8937cde77c7a'::uuid, 'drawdown-deploy-cool-roofs',
     'A screenshot or photo of your marked-up map or tally.',
     'Do this from online maps only; don''t go onto roofs or private property, leave your own home unmarked, and don''t single out individual homes or homeowners.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/deploy-cool-roofs), used with permission. Adapted: the mission wording is original.',
     'Cool roofs cut GHG emissions from electricity generation by lowering the amount of cooling required to condition indoor spaces, thereby decreasing the use of air conditioners. Using cool roofs in building design lowers electricity use, improves thermal comfort for building occupants, and is relatively cheap to deploy.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/deploy-cool-roofs', null, null, null),
    ('a6793da7-d182-5fa1-bf42-59bbc9796347'::uuid, 'drawdown-increase-decentralized-composting',
     'A photo of your work, with no one else''s face unless they agreed, or a short note on what you learned.',
     'Join an organized session, wear gloves and closed shoes, follow the site''s rules, and wash your hands afterward.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/increase-decentralized-composting), used with permission. Adapted: the mission wording is original.',
     'Decentralized composting systems involve waste generators in converting organic waste (OW) into a nutrient-rich soil supplement. They include a broad range of composting scales, from single households and community gardens to commercial and institutional operations (Platt, 2017).',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/increase-decentralized-composting', null, null, null),
    ('56b4c743-10a0-5148-ae60-323c3e0d1564'::uuid, 'drawdown-improve-fishing-vessel-efficiency',
     'A short summary of the conversation, with a photo only if you had permission.',
     'Ask politely, accept no for an answer, and share names or photos only with permission.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-fishing-vessel-efficiency), used with permission. Adapted: the mission wording is original.',
     'Improving fishing vessel efficiency cuts CO₂ emissions in wild capture fisheries by lowering fuel use through vessel, gear, or operational modifications. Advantages include the long-term cost savings from fuel use reductions, the ability to implement many of these improvements without reducing fishing effort, and the potential additional benefits for air quality and marine ecosystems.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-fishing-vessel-efficiency', null, null, null),
    ('cdc236e3-e4bd-5323-bcd4-ee9c4d77f135'::uuid, 'drawdown-improve-aquaculture',
     'A photo of your chart and the source for the label you looked up.',
     'Read labels without handling products unnecessarily, and ask staff politely if you have questions.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-aquaculture), used with permission. Adapted: the mission wording is original.',
     'Improving aquaculture involves reducing CO₂ and other GHG emissions during the production of farmed fish and other aquatic animals through better feed efficiency and the decarbonization of on-farm energy use. Advantages include reduced demand for feedstocks produced from both wild capture fisheries and terrestrial sources, which benefits marine and terrestrial ecosystems.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-aquaculture', null, null, null),
    ('da0a9a12-65d1-5a46-bcce-f359ebf13333'::uuid, 'drawdown-deploy-electric-irrigation-pumps',
     'A link or photo of your explainer with sources listed.',
     'Research and explain only; don''t touch or operate pumps, wells or electrical equipment.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/deploy-electric-irrigation-pumps), used with permission. Adapted: the mission wording is original.',
     'Replacing fossil-fuel-powered irrigation pumps with electric pumps powered by the grid can reduce emissions in most regions of the world. Electric irrigation pumps, which can also be powered by on-site clean energy, are more efficient than fossil fuel pumps. They are already cost-competitive and widely used, and adoption is increasing.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/deploy-electric-irrigation-pumps', null, null, null),
    ('fabf57f7-bd14-5ec5-a980-41397329157a'::uuid, 'drawdown-improve-manure-management',
     'Your summary with links to the agency''s rules or records, with no farm owners'' names or home addresses.',
     'Use public records only, don''t name farm owners or post their addresses, and never enter farms or go near manure storage, which can release deadly gases.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-manure-management), used with permission. Adapted: the mission wording is original.',
     'Improved manure management refers to the use of impermeable covers and physical or chemical treatments applied during the storage and processing of wet manure. These techniques can reduce methane emissions under anaerobic storage conditions and nitrous oxide emissions under aerobic conditions.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-manure-management', null, null, null),
    ('38f5c62c-a8cb-5ac4-b0b1-aba602a400d5'::uuid, 'drawdown-reduce-overfishing',
     'Your summary with links to the agency reports.',
     'Use official fisheries sources, and if you fish, follow local licenses and limits.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/reduce-overfishing), used with permission. Adapted: the mission wording is original.',
     'Reduce Overfishing refers to the use of management actions that decrease fishing effort and therefore cut CO₂ emissions from fishing vessel fuel use on overfished stocks. Advantages include the potential to replenish depleted fish stocks, support ecosystem health, and enhance long-term food and job security.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/reduce-overfishing', null, null, null),
    ('b5a1b342-9b1c-537e-920b-98226ad45669'::uuid, 'drawdown-protect-seafloors',
     'Your map or table with links to the sources.',
     'Research online, and if you visit the coast, stay in public areas and watch the tide.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/protect-seafloors), used with permission. Adapted: the mission wording is original.',
     'Protect Seafloors is the long-term protection of the seafloor from degradation, which helps preserve existing sediment carbon stocks and avoid CO₂ emissions. Advantages of seafloor protection include the conservation of biodiversity and marine ecosystems, potentially low costs, and the ability for immediate implementation.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/protect-seafloors', null, null, null),
    ('dfb7d2eb-1373-59ae-bacd-22668b604f68'::uuid, 'drawdown-restore-grasslands-savannas',
     'A photo of your identification card with sources listed.',
     'Photograph or draw plants instead of picking them, stay on trails, don''t touch plants you can''t identify, since some cause rashes or burns, and wash your hands afterward.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/restore-grasslands-savannas), used with permission. Adapted: the mission wording is original.',
     'Grassland and savanna restoration removes CO₂ from the atmosphere through photosynthesis as the ecosystem regrows, storing carbon in soils and vegetation. Grassland and savanna restoration faces relatively low barriers to implementation, provides substantial benefits for biodiversity, and may be deployable on large land areas.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/restore-grasslands-savannas', null, null, null),
    ('74a7935a-731f-5f35-ad12-f1799e22d378'::uuid, 'drawdown-restore-mangrove-ecosystems',
     'A photo of your labeled artwork.',
     'Use your own artwork, and if you visit mangroves, stay on public boardwalks and watch the tides.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/restore-mangrove-ecosystems), used with permission. Adapted: the mission wording is original.',
     'Restore Mangrove Ecosystems removes carbon by re-establishing mangrove forests in areas where they were previously destroyed by conversion or other disturbances. This allows carbon to accumulate in above- and below-ground biomass and sediment. Advantages include mangrove forests'' high effectiveness at carbon removal and storage, as well as their numerous environmental benefits and generally low cost.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/restore-mangrove-ecosystems', null, null, null),
    ('96685219-f741-5c38-97ad-cdc5eceba121'::uuid, 'drawdown-restore-salt-marsh-ecosystems',
     'A photo of your work, with no one else''s face unless they agreed, or a link to where you shared the project.',
     'Join only organized groups and follow the leaders'' safety briefing, wear gloves and sturdy shoes, check the tide and stay out of the water, leave sharp or hazardous items for the organizers, and stay off fragile marsh plants.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/restore-salt-marsh-ecosystems), used with permission. Adapted: the mission wording is original.',
     'Restore Salt Marsh Ecosystems involves actively reestablishing salt marshes in areas where they were previously lost to conversion or other disturbance, allowing vegetation to regrow and carbon to accumulate in biomass and sediments. Advantages include salt marshes’ ability to durably store substantial quantities of carbon over long time periods and their numerous co-benefits for the environment and humans.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/restore-salt-marsh-ecosystems', null, null, null),
    ('78ab0a5d-ca2b-52b2-a9d0-54827b5f3fd7'::uuid, 'drawdown-restore-seagrass-ecosystems',
     'A photo of your card and where you shared it.',
     'Base it on official guidance, and post or hand it out only where you have permission.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/restore-seagrass-ecosystems), used with permission. Adapted: the mission wording is original.',
     'Restore Seagrass Ecosystems involves reestablishing seagrass meadows in ocean areas where they were lost due to disturbances or degradation. As seagrasses grow, they remove CO₂ from ocean water through photosynthesis and accumulate carbon in their biomass, which allows seawater to take up additional CO₂ from the atmosphere.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/restore-seagrass-ecosystems', null, null, null),
    ('a4f79ed1-4534-57fc-a181-33e95fc87b0c'::uuid, 'drawdown-restore-seaweed-ecosystems',
     'Your summary with links to the project.',
     'Follow along online, and join any in-water activity only through the project''s official volunteer program.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/restore-seaweed-ecosystems), used with permission. Adapted: the mission wording is original.',
     'Seaweed (also called macroalgae) ecosystem restoration involves the reestablishment of wild red, brown, and green seaweed through interventions that recover degraded, damaged, or destroyed seaweed ecosystems. Healthy seaweed ecosystems remove CO₂ from the water column and convert it into biomass through photosynthesis, allowing additional CO₂ to be taken up in the ocean from the atmosphere.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/restore-seaweed-ecosystems', null, null, null),
    ('ff2a6de8-b97e-5642-acb6-25b39fcc4a9a'::uuid, 'drawdown-improve-fuel-burning-cooking-equipment',
     'A link or photo of your explainer with sources named.',
     'Share information from recognized sources without giving medical advice, and don''t test stoves or burn anything indoors.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-fuel-burning-cooking-equipment), used with permission. Adapted: the mission wording is original.',
     'In low- and middle-income countries, adopting cooking equipment that uses cleaner fuels or is more efficient has the potential to reduce GHG emissions from both cooking and deforestation due to unsustainable biomass use. Such equipment is readily available and inexpensive and provides significant social benefits. Barriers to adoption include cost and cultural practices, particularly in sub-Saharan Africa.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-fuel-burning-cooking-equipment', null, null, null),
    ('4f17538c-53b5-5c0e-9a9a-2d8ff007990f'::uuid, 'drawdown-deploy-electric-cooking-equipment',
     'A photo of your dish and recipe card.',
     'Follow the appliance instructions, don''t use damaged cords or overloaded outlets, and follow basic food safety.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/deploy-electric-cooking-equipment), used with permission. Adapted: the mission wording is original.',
     'Electric cooking equipment such as electric resistance stoves, induction stoves, and electric ovens can replace fuel-burning cooking equipment and reduce cooking-related GHG emissions, especially in regions with low-emission electricity grids. Cooking with electricity has significant health, safety, and energy efficiency benefits but cost, reliable access to electricity, and cultural compatibility are barriers to adoption.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/deploy-electric-cooking-equipment', null, null, null),
    ('9991a89f-e662-599f-84d2-e13c725e139d'::uuid, 'drawdown-deploy-district-cooling',
     'A photo of your diagram or comic with sources listed.',
     'Work from public sources and don''t visit plants or restricted utility areas.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/deploy-district-cooling), used with permission. Adapted: the mission wording is original.',
     'Deploying district cooling is the process of connecting multiple buildings in a dense area to a single, highly efficient source of cooling. The increased energy efficiency and reduction in use of high global warming potential refrigerants can translate into substantial emissions reductions and lower operating expenses (International Energy Agency [IEA], 2018; Energy Sector Management Assistance Program, 2020).',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/deploy-district-cooling', null, null, null)
  ) as v(mission_id, slug, proof_hint, safety_note, credit_line, about, about_credit, source_url, license_name,
        license_url, doi)
on conflict (mission_id) do nothing;

commit;
